 return{c,api,calls,caps,setFeedbackError:v=>{feedbackError=v},setFeedbackConfirmError:v=>{feedbackConfirmError=v},setAgent:v=>{a=v},setKnowledge:v=>{knowledge=v},setMemories:v=>{memoryRows=v},setDecisionError:v=>{decisionError=v},setModels:v=>{modelRows=v},setUnavailable:v=>{unavailable=v},setOwner:v=>{owner=v},setDetail:v=>{d=v},setFeedback:v=>{f=v},async start(){await c.activate();await settle(()=>!c.snapshot().runs.loading);await c.selectAgent(spec);await settle(()=>!c.snapshot().memories.loading);await c.selectRun(run,spec);await settle(()=>!c.snapshot().feedback.loading);return c}}
