test('missing or changed preparation blocks submission before any task POST',async()=>{let denied=false;const f=fixture({preparation:prepPorts({resources:async()=>{if(denied)throw Error('synthetic no metadata');return emptyResources()}})});await f.start();const done=detail();done.run.status='succeeded';done.run.finished_at=stamp;done.pending_effect=null;f.setDetail(done);await f.c.refresh();denied=true;await f.c.submit('DEMO task',3);assert.equal(f.calls.filter(x=>x.kind==='submit').length,0);assert.equal(f.c.snapshot().preparation,null);f.c.dispose()})
test('editing launch draft during confirmation invalidates consent and sends no POST',async()=>{let release;const f=fixture({preparation:prepPorts(),confirm:()=>new Promise(r=>release=r)});await f.start();const pending=f.c.submit('DEMO task',3);await settle(()=>Boolean(release));f.c.retireRunDraft();release(true);await pending;assert.equal(f.calls.filter(x=>x.kind==='submit').length,0);f.c.dispose()})

test('real launch forwards review, selected device and reviewed_v1 in the existing Native argument order',async()=>{const f=fixture({caps:{agent_human_input_available:true,agent_human_responses_enabled:true},preparation:prepPorts()});await f.start();await f.c.submit('DEMO reviewed task',3,undefined,{requirePlanReview:true,structuredPlanning:true,localDeviceId:''});const submitted=f.calls.find(x=>x.kind==='submit');assert.ok(submitted);assert.equal(submitted.args[0],spec);assert.equal(submitted.args[1],1);assert.equal(submitted.args[5],true);assert.equal(submitted.args[8],undefined);assert.equal(submitted.args[10],'reviewed_v1');assert.equal(f.c.snapshot().runs.pendingSubmit.taskPlanning,'reviewed_v1');f.c.dispose()})

test('resource choice A-B-A retires launch consent without resetting the quality editor epoch',async()=>{let release;const f=fixture({caps:{agent_human_input_available:true,agent_human_responses_enabled:true},preparation:prepPorts(),confirm:()=>new Promise(r=>release=r)});await f.start();const before=f.c.snapshot().qualitySelectionEpoch,pending=f.c.submit('DEMO task',3);await settle(()=>Boolean(release));await f.c.refreshPreparation({localDeviceId:'',structuredPlanning:true});await f.c.refreshPreparation({localDeviceId:'',structuredPlanning:false});assert.equal(f.c.snapshot().qualitySelectionEpoch,before);release(true);await pending;assert.equal(f.calls.filter(x=>x.kind==='submit').length,0);f.c.dispose()})

test('valid Native HTTP aliases remain one displayed grant and require exact real binding metadata',async()=>{const name='http_c'+model.replaceAll('-',''),binding={name,description:'read demo',connection_id:model,connection_revision:1},a=agent();a.spec.tools.push(name);a.spec.http_tools=[binding];const resources=emptyResources();resources.bindings.http=[binding];resources.connectedHttp=[{name,description:'read demo',method:'GET',status:'ok'}];const actual=await readOriginalRunPreparation(prepArgs({agent:a,ports:prepPorts({resources:async()=>resources})}));assert.equal(actual.readiness.ready,true);assert.deepEqual(originalRunStructuredSpec(originalRunAgent(a,employee).spec,a.spec).tools.filter(x=>x===name),[name])})

test('A legacy Role fourth argument remains accepted and forwarded in Native SDK slot eleven',async()=>{const f=fixture({caps:{agent_human_input_available:true,agent_human_responses_enabled:true},preparation:prepPorts()});await f.start();await f.c.submit('DEMO role task',3,undefined,{taskPlanning:'reviewed_v1'});const post=f.calls.find(x=>x.kind==='submit');assert.ok(post);assert.equal(post.args[5],true);assert.equal(post.args[10],'reviewed_v1');assert.equal(f.c.snapshot().runs.pendingSubmit.taskPlanning,'reviewed_v1');f.c.dispose()})
test('A Role business launcher refusal is retained for legacy and full C launch options',async()=>{for(const options of [{taskPlanning:'reviewed_v1'},{requirePlanReview:true,structuredPlanning:true,localDeviceId:''}]){const f=fixture({caps:{agent_human_input_available:true,agent_human_responses_enabled:true},preparation:prepPorts()});await f.start();await assert.rejects(()=>f.c.submit('DEMO task',3,{case_id:memory},options),/original_role_business_launcher_not_supported/);assert.equal(f.calls.filter(x=>x.kind==='submit').length,0);f.c.dispose()}})
test('A planning input validation rejects invalid mode and contradictory C switch before POST',async()=>{for(const options of [{taskPlanning:'wrong'},{taskPlanning:'reviewed_v1',structuredPlanning:false},{structuredPlanning:true,requirePlanReview:false,localDeviceId:''}]){const f=fixture({preparation:prepPorts()});await f.start();await assert.rejects(()=>f.c.submit('DEMO task',3,undefined,options));assert.equal(f.calls.filter(x=>x.kind==='submit').length,0);f.c.dispose()}})
test('optional real Role profile discovery distinguishes unavailable feature from plain run readiness',async()=>{let calls=0;const value=await readOriginalRunPreparation(prepArgs({probeRoleProfile:true,ports:prepPorts({roleMeta:async()=>{calls++;throw Error('feature unavailable')}})}));assert.equal(calls,1);assert.equal(value.roleProfileReady,false);assert.equal(value.readiness.ready,true);const available=await readOriginalRunPreparation(prepArgs({probeRoleProfile:true}));assert.equal(available.roleProfileReady,true)})
const admittedRole=()=>({protocol:'original_role_owner_v1',run_id:run,spec_id:spec,spec_revision:1,base_spec_sha256:hash,spec_snapshot:{...agent().spec,roles:[{id:'analyst',name:'分析',responsibility:'计算',tasks:['计算'],inputs:[],deliverables:['值'],depends_on:[],tools:['calculate'],done_criteria:['真实结果'],skill_refs:[]}],capability_requirements:[]},role_state:{version:1,completed:[],outputs:{},active_role_id:'analyst',started_role_id:''}})
test('C detail projection preserves A admitted role snapshot and checkpoint prefix',()=>{const d=detail();d.original_role=admittedRole();const projected=originalRunDetail(d,employee);assert.equal(projected.spec_snapshot.roles[0].id,'analyst');assert.equal(projected.checkpoint.role_state.active_role_id,'analyst');assert.equal(projected.spec_name.includes('CURRENT TITLE'),false);d.original_role.spec_revision=2;assert.throws(()=>originalRunDetail(d,employee),/original_role_owner_projection_invalid/)})
test('revoked source hides A role snapshot, role state and result together',()=>{const d=detail();d.original_role=admittedRole();d.knowledge_outputs_available=false;d.run.result_text='DO NOT DISPLAY';const projected=originalRunDetail(d,employee);assert.equal(projected.result,'');assert.equal(projected.spec_snapshot,undefined);assert.equal(projected.checkpoint.role_state,undefined)})

// Preserve response certainty through the original page privacy boundary.
for(const status of [403,404])test('definitive feedback denial hides privacy but permits a fresh task after verified recovery '+status,async()=>{
 const f=fixture();try{const d=detail();d.run.status='succeeded';d.run.finished_at=stamp;d.pending_effect=null;f.setDetail(d);await f.start();f.setFeedbackError(new PgNativePilotError(status,'synthetic_definitive_feedback_denial'));
 await f.c.submitFeedback({rating:'up',tags:[],comment:'PRIVATE_FEEDBACK'});const hidden=f.c.snapshot();assert.equal(hidden.sourceDenied,true);assert.equal(hidden.activeRun,null);assert.deepEqual(hidden.agents,[]);assert.equal(await f.c.prepareNewTask(),false);
 await f.c.verifyIdentity();const restored=f.c.snapshot();assert.equal(restored.sourceDenied,false);assert.equal(restored.closed,false);assert.equal(restored.feedback.pending,null);assert.equal(restored.activeRun.id,run);assert.equal(await f.c.prepareNewTask(),true);assert.equal(f.c.snapshot().activeRun,null);assert.equal(f.c.snapshot().selectedAgentId,spec);assert.deepEqual(f.calls.map(v=>v.kind),['feedback-change']);
 }finally{f.c.dispose()}
})
for(const denial of [new PgNativePilotError(503,'synthetic_service_unavailable'),Error('synthetic_response_lost')])test('unknown feedback result remains blocked and confirms only its original request '+denial.message,async()=>{
 const f=fixture();try{const d=detail();d.run.status='succeeded';d.run.finished_at=stamp;d.pending_effect=null;f.setDetail(d);await f.start();f.setFeedbackError(denial);await f.c.submitFeedback({rating:'up',tags:[],comment:'ORIGINAL_PRIVATE_FEEDBACK'});const pending=f.c.snapshot().feedback.pending;assert(pending);await f.c.verifyIdentity();assert.deepEqual(f.c.snapshot().feedback.pending,pending);assert.equal(await f.c.prepareNewTask(),false);await f.c.submitFeedback({rating:'down',tags:[],comment:'REPLACEMENT_MUST_NOT_SUBMIT'});assert.deepEqual(f.calls.map(v=>v.kind),['feedback-change','feedback-confirm']);assert.deepEqual(f.calls[1].body,f.calls[0].body);assert.equal(f.calls[1].body.comment,'ORIGINAL_PRIVATE_FEEDBACK');
 }finally{f.c.dispose()}
})
test('a later confirm403 cannot erase an already unknown feedback operation',async()=>{
 const f=fixture();try{const d=detail();d.run.status='succeeded';d.run.finished_at=stamp;d.pending_effect=null;f.setDetail(d);await f.start();await f.c.submitFeedback({rating:'up',tags:[],comment:'ORIGINAL_PRIVATE_FEEDBACK'});const pending=f.c.snapshot().feedback.pending;assert(pending);f.setFeedbackConfirmError(new PgNativePilotError(403,'synthetic_confirmation_denied'));await f.c.submitFeedback({rating:'down',tags:[],comment:'REPLACEMENT_MUST_NOT_SUBMIT'});assert.equal(f.c.snapshot().sourceDenied,true);await f.c.verifyIdentity();assert.deepEqual(f.c.snapshot().feedback.pending,pending);assert.equal(await f.c.prepareNewTask(),false);assert.deepEqual(f.calls.map(v=>v.kind),['feedback-change','feedback-confirm']);assert.deepEqual(f.calls[1].body,f.calls[0].body);
 }finally{f.c.dispose()}
})

